import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Article Model","description":"","frontmatter":{},"headers":[],"relativePath":"backend/models/article.md","filePath":"backend/models/article.md"}`),a={name:`backend/models/article.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="article-model" tabindex="-1">Article Model <a class="header-anchor" href="#article-model" aria-label="Permalink to &quot;Article Model&quot;">​</a></h1><p><code>app/Models/Article.php</code> is the central model of the TechyNews platform. It represents published news stories, drafted AI articles, and localized content.</p><h2 id="database-schema-columns" tabindex="-1">Database Schema &amp; Columns <a class="header-anchor" href="#database-schema-columns" aria-label="Permalink to &quot;Database Schema &amp; Columns&quot;">​</a></h2><ul><li><code>id</code> (Primary Key)</li><li><code>title</code> (String): Original language headline.</li><li><code>slug</code> (String): Unique, SEO-friendly URL identifier.</li><li><code>summary</code> (Text): AI-generated short description for grid layouts.</li><li><code>content</code> (LongText): Stored as <strong>RAW HTML</strong>. This is a strict architectural rule to ensure instant rendering without frontend parsing delays.</li><li><code>translations</code> (JSON): The magic column for i18n. Stores locale overrides. Example structure: <code>{&quot;es&quot;: {&quot;title&quot;: &quot;...&quot;, &quot;summary&quot;: &quot;...&quot;, &quot;content&quot;: &quot;...&quot;}}</code>.</li><li><code>cover_image_path</code> (String): Unsplash API image URL.</li><li><code>status</code> (Enum/String): <code>draft</code>, <code>published</code>, <code>archived</code>.</li></ul><h2 id="key-methods-attributes" tabindex="-1">Key Methods &amp; Attributes <a class="header-anchor" href="#key-methods-attributes" aria-label="Permalink to &quot;Key Methods &amp; Attributes&quot;">​</a></h2><h3 id="gettranslatedattribute-key-locale" tabindex="-1"><code>getTranslatedAttribute($key, $locale)</code> <a class="header-anchor" href="#gettranslatedattribute-key-locale" aria-label="Permalink to &quot;`getTranslatedAttribute($key, $locale)`&quot;">​</a></h3><p>This method overrides the default attribute access. If the user&#39;s current locale is &#39;es&#39;, accessing <code>$article-&gt;title</code> will transparently check the <code>translations</code> JSON column for an &#39;es&#39; key. If it exists, it returns the Spanish title; otherwise, it falls back to the original string.</p><h3 id="sanitizecontent" tabindex="-1"><code>sanitizeContent()</code> <a class="header-anchor" href="#sanitizecontent" aria-label="Permalink to &quot;`sanitizeContent()`&quot;">​</a></h3><p>Before any data is pushed to the frontend via Inertia, the <code>content</code> is passed through an HTML purifier. The model itself doesn&#39;t purify on save (to preserve AI generation quirks that can be fixed later), but it must be purified on read to prevent XSS.</p><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to &quot;Relationships&quot;">​</a></h2><ul><li><code>belongsToMany(Category::class)</code>: Many-to-many relationship for grouping.</li><li><code>belongsToMany(Tag::class)</code>: Granular metadata tagging.</li><li><code>hasMany(FactCheck::class)</code>: Zero-to-many relationship with automated AI fact-checking reports.</li></ul>',11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};